from fastapi import FastAPI, TestClient
from fastapi.testclient import TestClient

app = FastAPI()

@app.vibe("/vibe")
def vibe_route():
    return {"message": "vibing"}

client = TestClient(app)

def test_vibe_route():
    response = client.get("/vibe") # Note: using get here because we don't know if @app.vibe is GET or custom
    # If @app.vibe is mapped to "VIBE" method, we might need client.request("VIBE", "/vibe")
    print(f"Response: {response}")
    assert response.status_code == 200
    assert response.json() == {"message": "vibing"}

def test_vibe_route_custom_method():
    response = client.request("VIBE", "/vibe")
    print(f"Response: {response}")
    assert response.status_code == 200
    assert response.json() == {"message": "vibing"}

